import { createHmac, timingSafeEqual } from "node:crypto";

/**
 * One-click unsubscribe (CAN-SPAM) has to work without an authenticated
 * session, so the link itself carries a token proving it was generated by
 * us for this exact user. Signed with AUTH_SECRET, but under its own
 * "unsubscribe:" label so the MAC can never stand in for anything else that
 * key signs.
 */
function secret(): string {
  const s = process.env.AUTH_SECRET;
  if (!s) throw new Error("AUTH_SECRET is not set");
  return s;
}

export function unsubscribeToken(userId: string): string {
  return createHmac("sha256", secret()).update(`unsubscribe:${userId}`).digest("hex");
}

// Links in emails sent before 2.9.2 were signed over the bare userId. They
// keep working until recipients have had a couple of months of new emails;
// after this date only the labelled token above verifies.
const LEGACY_TOKENS_UNTIL = Date.parse("2027-01-31T00:00:00Z");

function legacyToken(userId: string): string {
  return createHmac("sha256", secret()).update(userId).digest("hex");
}

function sameHex(expected: string, token: string): boolean {
  // Buffer.from(..., "hex") stops at the first non-hex character rather than
  // failing, so a valid token with junk appended would otherwise pass.
  if (!/^[0-9a-f]{64}$/.test(token)) return false;
  const a = Buffer.from(expected, "hex");
  const b = Buffer.from(token, "hex");
  return a.length === b.length && timingSafeEqual(a, b);
}

export function verifyUnsubscribeToken(userId: string, token: string): boolean {
  if (sameHex(unsubscribeToken(userId), token)) return true;
  return Date.now() < LEGACY_TOKENS_UNTIL && sameHex(legacyToken(userId), token);
}
